import re
import glob

def process_file(filepath):
    with open(filepath, 'r', encoding='utf-8') as f:
        content = f.read()

    # Dictionary of specific level replacements for Series 1-5 (RU only for now since game is in RU/EN, but descriptions in code seem to be mostly strings. I'll make them rich).
    
    replacements = {
        # Series 1
        "Обучение азам и навигации по высотам. Цель: научитесь строить, раскапывать и преодолейте космическую улитку высот.": "БАЗОВЫЙ ПРОТОКОЛ. Изучите основы навигации в многоуровневом пространстве. Овладейте терраформингом (Строительство и Бурение), чтобы преодолеть спиральную аномалию и достичь Портала.",
        "Добывайте строительные материалы и проложите путь к Столице холмов.": "СБОР РЕСУРСОВ. Локация нестабильна. Добывайте строительные материалы (ОД), избегая обрушения хрупких платформ, чтобы проложить безопасный маршрут к Столице.",
        "Снизьте высоту центрального гекса, соблюдая правила геологической стабильности.": "ПРОТОКОЛ ВЫРАВНИВАНИЯ. Центральный сектор опасно возвышен. Используйте бурение для поэтапного снижения высоты до базового уровня, не нарушая геологический баланс.",
        "Соберите 10 кредитов. Используйте шахты и планирование ресурсов.": "ФИНАНСОВЫЙ ЦИКЛ. Энергия системы истощена. Соберите 10 кредитов, грамотно распределяя ходы между поиском ресурсов и прокладкой шахт.",
        "Прокладывайте мосты через обрывы. Возвышайте гексы, чтобы не упасть.": "СТРУКТУРНАЯ ИНЖЕНЕРИЯ. Сектор изозолирован пропастями. Возводите платформы, чтобы создать устойчивые мосты и пересечь пустотные разломы.",
        "Познакомьтесь с энтропией. Каждое действие увеличивает нестабильность. Дойдите до финиша до коллапса.": "ЭНТРОПИЙНЫЙ КОЛЛАПС. Внимание: каждое ваше действие дестабилизирует кластер. Рассчитайте оптимальный маршрут и доберитесь до точки выхода до достижения критической энтропии.",
        "Удерживайте стабильность сектора.": "БАРЬЕР СТАБИЛЬНОСТИ. Удерживайте уровень стабильности в допустимых пределах, нейтрализуя очаги гравитационных возмущений.",
        "Двойная задача: добыть кредиты и добраться до выхода, балансируя ресурсы.": "КРОСС-СИНХРОНИЗАЦИЯ. Сбалансируйте добычу кредитов и продвижение к выходу. Растрата ресурсов приведет к блокировке систем жизнеобеспечения.",
        "Откройте скрытый путь.": "НАВИГАЦИОННАЯ АНОМАЛИЯ. Видимых путей нет. Исследуйте структуру кластера и используйте терраформинг для выявления скрытых маршрутов к цели.",
        "Анализируйте окружение, чтобы найти выход в нестабильной зоне.": "ДИНАМИЧЕСКИЙ АНАЛИЗ. Зона подвержена непредсказуемым пространственным сдвигам. Изучайте ландшафт и адаптируйтесь к изменениям.",
        "Прорвитесь через барьеры.": "КИНЕТИЧЕСКИЙ ПРОРЫВ. Прямой маршрут заблокирован массивными геологическими барьерами. Используйте всю доступную энергию для их преодоления.",
        
        # Series 2
        "Активируйте центральный Монолит, найдя обходной путь к нему.": "АРХЕОЛОГИЧЕСКИЙ ЦИКЛ. Центральный Монолит заблокирован непреодолимой стеной. Исследуйте внешние хребты и найдите обходной путь для его активации.",
        "Соберите три подземных артефакта и активируйте Монолит.": "ГЛУБИННОЕ СКАНИРОВАНИЕ. Ключи активации скрыты в недрах кластера. Проведите глубокое бурение, соберите артефакты и запустите Монолит.",
        "Доберитесь до Монолита в условиях нестабильности. Стройте опоры для подъема.": "ВЕРТИКАЛЬНАЯ АДАПТАЦИЯ. Нестабильный сектор с резкими перепадами высот. Возводите ступенчатые опоры для безопасного восхождения к Монолиту.",
        "Активируйте Обелиск для рассеивания барьера и запуска Монолита.": "ПОДАВЛЕНИЕ ПОЛЯ. Энергетический барьер блокирует Монолит. Сначала найдите и активируйте периферийный Обелиск для снятия защиты.",
        "Постройте цельную Линию из трех смежных возвышенных блоков.": "ГЕОМЕТРИЯ: ЛИНИЯ. Протокол требует создания линейного резонанса. Возведите цельную линию из трех смежных возвышенных платформ.",
        "Постройте Треугольник из возвышенных гексов и защитите плиты от бота.": "ГЕОМЕТРИЯ: ТРЕУГОЛЬНИК. Постройте треугольный контур. Внимание: зафиксирована активность враждебного ИИ. Защищайте свои платформы от разрушения.",
        "Выстройте геометрический Ромб из четырех смежных плит высокого уровня.": "ГЕОМЕТРИЯ: РОМБ. Сформируйте ромбовидную структуру из четырех смежных возвышенных плит для калибровки энергетической сети.",
        "Постройте замкнутое Кольцо вокруг центральной Пустоты.": "ГЕОМЕТРИЯ: КОЛЬЦО. Изолируйте центральную пространственную аномалию, выстроив вокруг нее сплошное замкнутое кольцо платформ.",
        "Сформируйте сложные геометрические конструкции, сдерживая разрушения бота.": "АРХИТЕКТУРНОЕ ПРОТИВОСТОЯНИЕ. Возведите сложные геометрические формации в условиях непрерывного саботажа со стороны вражеских дронов.",
        "Финальный синтез: активируйте защитные обелиски и запустите Монолит.": "СИНТЕЗ. Критическая фаза. Активируйте защитные обелиски по периметру и запустите Монолит до того, как кластер схлопнется."
    }

    for old_text, new_text in replacements.items():
        # Using a regex replacement to handle exact matches inside quotes
        pattern = r"(?<=description: ')[^']*(?=')"
        
        def replace_func(match):
            text = match.group(0)
            if text == old_text:
                return new_text
            return text
            
        content = re.sub(pattern, replace_func, content)

    with open(filepath, 'w', encoding='utf-8') as f:
        f.write(content)

for filepath in glob.glob('campaign/*.ts'):
    process_file(filepath)
